            creature->SetDisplayId(target->GetDisplayId());
            creature->SetObjectScale(0.5f);
        }

        return true;
    }

    if (show == "last")
    {
        handler->PSendSysMessage("|cff00ff00DEBUG: wp last, PathID: |r|cff00ffff%u|r", pathid);

        WorldDatabasePreparedStatement* stmt = WorldDatabase.GetPreparedStatement(WORLD_SEL_WAYPOINT_DATA_POS_LAST_BY_ID);
        stmt->setUInt32(0, pathid);
        PreparedQueryResult result = WorldDatabase.Query(stmt);

        if (!result)
        {
            handler->PSendSysMessage(LANG_WAYPOINT_NOTFOUNDLAST, pathid);
            handler->SetSentErrorMessage(true);
            return false;
        }
        Field* fields = result->Fetch();
        float x = fields[0].GetFloat();
        float y = fields[1].GetFloat();
        float z = fields[2].GetFloat();
        float o = fields[3].GetFloat();
        uint32 id = VISUAL_WAYPOINT;

        Player* chr = handler->GetSession()->GetPlayer();
        Map* map = chr->GetMap();

        Creature* creature = new Creature;
        if (!creature->Create(sObjectMgr->GetGenerator<HighGuid::Creature>()->Generate(), map, chr->GetPhaseMgr().GetPhaseMaskForSpawn(), id, 0, 0, x, y, z, o))
        {
            handler->PSendSysMessage(LANG_WAYPOINT_NOTCREATED, id);
            delete creature;
            return false;
        }

        creature->SaveToDB(map->GetId(), (UI64LIT(1) << map->GetSpawnMode()), chr->GetPhaseMgr().GetPhaseMaskForSpawn());
        if (!creature->LoadCreatureFromDB(creature->GetDBTableGUIDLow(), map))
        {
            handler->PSendSysMessage(LANG_WAYPOINT_NOTCREATED, id);
            delete creature;
            return false;
        }

        if (target)
        {
            creature->SetDisplayId(target->GetDisplayId());
            creature->SetObjectScale(0.5f);
        }

        return true;
    }

    if (show == "off")
    {
        WorldDatabasePreparedStatement* stmt = WorldDatabase.GetPreparedStatement(WORLD_SEL_CREATURE_BY_ID);
        stmt->setUInt32(0, 1);
        PreparedQueryResult result = WorldDatabase.Query(stmt);

        if (!result)
        {
            handler->SendSysMessage(LANG_WAYPOINT_VP_NOTFOUND);
            handler->SetSentErrorMessage(true);
            return false;
        }
        bool hasError = false;
        do
        {
            Field* fields = result->Fetch();
            uint32 guid = fields[0].GetUInt64();
            Player* chr = handler->GetSession()->GetPlayer();
            Creature* creature = handler->GetSession()->GetPlayer()->GetMap()->GetCreature(ObjectGuid::Create<HighGuid::Creature>(chr->GetMapId(), VISUAL_WAYPOINT, guid));
            if (!creature)
            {
                handler->PSendSysMessage(LANG_WAYPOINT_NOTREMOVED, guid);
